steps.codeExample:
public record Cafe(String nome, double preco) {}

var menu = List.of(new Cafe("Expresso", 8), new Cafe("Geisha", 24));
var premium = menu.stream()
  .filter(c -> c.preco() > 15)
  .map(Cafe::nome)
  .toList();
System.out.println(premium);

